import { Group, Mesh, PlaneGeometry } from 'three/webgpu';
import { MeshBasicNodeMaterial, texture, color } from 'three/tsl';
import { gsap } from 'gsap';
import '@/primitives';
import '@/text';

export default function createNode(config, ctx) {
	// Root group
	const root = new Group();

	// Apply placement
	if (config.position && config.position.length === 3) {
		root.position.set(config.position[0], config.position[1], config.position[2]);
	}
	if (config.rotation && config.rotation.length === 3) {
		root.rotation.set(config.rotation[0], config.rotation[1], config.rotation[2]);
	}
	if (config.scale && config.scale.length === 3) {
		root.scale.set(config.scale[0], config.scale[1], config.scale[2]);
	}

	// ------------ Background plane with brushed metal texture ------------
	const metalTex = ctx.textureLoader.load('/prism-assets/chrome/brushed-metal.map.png');

	const bgGeom = new PlaneGeometry(2, 0.5);
	const bgMat = new MeshBasicNodeMaterial({
		mapNode: texture(metalTex)
	});
	const bgMesh = new Mesh(bgGeom, bgMat);
	root.add(bgMesh);

	// ------------ Text overlay using MSDF atlas ------------
	// Retrieve atlas region (texture + UV transform info)
	const atlasRegion = ctx.fontAtlas.getRegion(0, {
		x: 0,
		y: 0,
		width: 512,
		height: 320
	});

	const txtTex = atlasRegion.texture;
	const txtMapNode = texture(txtTex);
	const txtColorNode = color('#16161d'); // ink color

	const txtMat = new MeshBasicNodeMaterial({
		mapNode: txtMapNode,
		colorNode: txtColorNode,
		transparent: true
	});

	const txtGeom = bgGeom.clone(); // same size, separate geometry for proper disposal
	const txtMesh = new Mesh(txtGeom, txtMat);
	// Slight forward offset to avoid z‑fighting with background
	txtMesh.position.z = 0.001;
	root.add(txtMesh);

	// ------------ User data: handlers & cleanup ------------
	root.userData.handlers = {};

	root.userData.cleanup = () => {
		// Dispose materials
		bgMat.dispose();
		txtMat.dispose();

		// Dispose geometries
		bgGeom.dispose();
		txtGeom.dispose();

		// Dispose textures (if they aren't shared cache)
		if (metalTex && typeof metalTex.dispose === 'function') metalTex.dispose();
		if (txtTex && typeof txtTex.dispose === 'function') txtTex.dispose();

		// Kill any GSAP timelines that might have been created elsewhere
		gsap.globalTimeline.clear();
	};

	// ------------ Apply cinematic primitives if any ------------
	if (Array.isArray(config.cinematicPrimitives)) {
		for (const primitive of config.cinematicPrimitives) {
			const fn = ctx.primitives[primitive.name];
			if (typeof fn === 'function') {
				fn(root, primitive.params);
			}
		}
	}

	return root;
}
